import{_ as e,o as a,c as s,a2 as i}from"./chunks/framework.CWdVbaJB.js";const u=JSON.parse('{"title":"API Reference","description":"","frontmatter":{"title":"API Reference"},"headers":[],"relativePath":"api-reference/index.md","filePath":"api-reference/index.md"}'),r={name:"api-reference/index.md"};function d(o,t,n,h,l,c){return a(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="api-reference" tabindex="-1">API Reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to &quot;API Reference&quot;">​</a></h1><p>The SHAVIRA API is a RESTful JSON API served on port 4000 by default.</p><h2 id="base-url" tabindex="-1">Base URL <a class="header-anchor" href="#base-url" aria-label="Permalink to &quot;Base URL&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://localhost:4000</span></span></code></pre></div><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>Most endpoints require authentication via one of two methods:</p><h3 id="session-cookies" tabindex="-1">Session Cookies <a class="header-anchor" href="#session-cookies" aria-label="Permalink to &quot;Session Cookies&quot;">​</a></h3><p>After login, the API sets HTTP-only cookies:</p><ul><li><code>shv_token</code> — access token (8h lifetime)</li><li><code>shv_refresh</code> — refresh token (30d lifetime)</li></ul><p>Cookies are sent automatically by the browser. For programmatic use, include <code>credentials: &quot;include&quot;</code> in fetch requests.</p><h3 id="api-keys" tabindex="-1">API Keys <a class="header-anchor" href="#api-keys" aria-label="Permalink to &quot;API Keys&quot;">​</a></h3><p>For SDK and collector integrations:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization: Bearer shv_your_api_key</span></span></code></pre></div><p>API keys use the <code>shv_</code> prefix and are stored as SHA-256 hashes.</p><h3 id="auth-levels" tabindex="-1">Auth Levels <a class="header-anchor" href="#auth-levels" aria-label="Permalink to &quot;Auth Levels&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Level</th><th>Description</th></tr></thead><tbody><tr><td><strong>Public</strong></td><td>No authentication required</td></tr><tr><td><strong>Authenticated</strong></td><td>Any logged-in user or valid API key</td></tr><tr><td><strong>Admin</strong></td><td>Requires <code>role: &quot;admin&quot;</code></td></tr></tbody></table><h2 id="response-format" tabindex="-1">Response Format <a class="header-anchor" href="#response-format" aria-label="Permalink to &quot;Response Format&quot;">​</a></h2><p>All responses are JSON. Successful responses return the data directly or wrapped in an object:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;sessions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;total&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">42</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><h2 id="error-format" tabindex="-1">Error Format <a class="header-anchor" href="#error-format" aria-label="Permalink to &quot;Error Format&quot;">​</a></h2><p>Errors return a JSON object with an <code>error</code> or <code>message</code> field:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Validation failed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;details&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span></code></pre></div><h3 id="status-codes" tabindex="-1">Status Codes <a class="header-anchor" href="#status-codes" aria-label="Permalink to &quot;Status Codes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>200</code></td><td>Success</td></tr><tr><td><code>201</code></td><td>Created</td></tr><tr><td><code>400</code></td><td>Validation error</td></tr><tr><td><code>401</code></td><td>Unauthorized</td></tr><tr><td><code>403</code></td><td>Forbidden</td></tr><tr><td><code>404</code></td><td>Not found</td></tr><tr><td><code>409</code></td><td>Conflict (duplicate)</td></tr><tr><td><code>429</code></td><td>Rate limited</td></tr><tr><td><code>500</code></td><td>Server error</td></tr><tr><td><code>503</code></td><td>Service unavailable</td></tr></tbody></table><h2 id="rate-limiting" tabindex="-1">Rate Limiting <a class="header-anchor" href="#rate-limiting" aria-label="Permalink to &quot;Rate Limiting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint Group</th><th>Limit</th></tr></thead><tbody><tr><td>Login</td><td>5 attempts per email/IP</td></tr><tr><td>Sessions/End Users</td><td>120 requests/min per user</td></tr><tr><td>Exports</td><td>20 per hour per workspace</td></tr><tr><td>SSE Connections</td><td>5 concurrent per workspace</td></tr></tbody></table><h2 id="workspace-scoping" tabindex="-1">Workspace Scoping <a class="header-anchor" href="#workspace-scoping" aria-label="Permalink to &quot;Workspace Scoping&quot;">​</a></h2><p>All data queries are automatically scoped to the authenticated user&#39;s workspace. You never need to pass a workspace ID — it&#39;s inferred from your session or API key.</p><h2 id="rbac" tabindex="-1">RBAC <a class="header-anchor" href="#rbac" aria-label="Permalink to &quot;RBAC&quot;">​</a></h2><ul><li><strong>Admins</strong> see all data in the workspace</li><li><strong>Members</strong> see only data in projects they&#39;re assigned to, plus workspace-level data (traces without a project)</li></ul><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>Endpoints</th></tr></thead><tbody><tr><td><a href="./ingest.html">Ingest</a></td><td><code>POST /api/ingest</code>, <code>POST /v1/traces</code></td></tr><tr><td><a href="./traces.html">Traces</a></td><td><code>GET /api/traces</code>, <code>GET /api/traces/stream</code></td></tr><tr><td><a href="./findings.html">Findings</a></td><td><code>GET /api/findings</code>, status/assign/comment/bulk</td></tr><tr><td><a href="./sessions.html">Sessions</a></td><td><code>GET /api/sessions</code>, events, end users</td></tr><tr><td><a href="./projects.html">Projects</a></td><td><code>GET/POST/PATCH /api/v2/projects</code>, members</td></tr><tr><td><a href="./detection-rules.html">Detection Rules</a></td><td>CRUD, validate, test, versions, export</td></tr><tr><td><a href="./auth.html">Auth</a></td><td>Signup, login, OAuth, API keys</td></tr><tr><td><a href="./admin.html">Admin</a></td><td>User management, pricing, workspace</td></tr></tbody></table>',33)])])}const k=e(r,[["render",d]]);export{u as __pageData,k as default};
